import{_ as s,o as e,c as p,a2 as o}from"./chunks/framework.EUByU7Iq.js";const h=JSON.parse('{"title":"《一握之砂 · 秋风惬意时》","description":"","frontmatter":{"title":"《一握之砂 · 秋风惬意时》","date":"2026-11-19T00:00:00.000Z","categories":["美文","一握之砂"],"collection":"《一握之砂 · 秋风惬意时》","tags":["一握之砂","日本"],"poem":true,"poem_quote":false,"merged":true,"pieces":51,"author":"石川啄木","source_book":"一握之砂"},"headers":[],"relativePath":"blogs/一握之砂·秋风惬意时/index.md","filePath":"blogs/一握之砂·秋风惬意时/index.md"}'),l={name:"blogs/一握之砂·秋风惬意时/index.md"};function t(i,a,n,c,r,d){return e(),p("div",null,[...a[0]||(a[0]=[o('<h1 id="《一握之砂-·-秋风惬意时》" tabindex="-1">《一握之砂 · 秋风惬意时》 <a class="header-anchor" href="#《一握之砂-·-秋风惬意时》" aria-label="Permalink to &quot;《一握之砂 · 秋风惬意时》&quot;">​</a></h1><p class="poem-meta">日本 · 石川啄木（1886—1912）　·　编者自译</p><p>全 51 首，收录完整。</p><div class="merged-book"><h3 id="第1首" tabindex="-1">第1首 <a class="header-anchor" href="#第1首" aria-label="Permalink to &quot;第1首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">故乡的天，竟这样远</p><p class="poem-stanza">我一个人登上高楼</p><p class="poem-stanza">怀着愁，又走下来</p></div><h3 id="第2首" tabindex="-1">第2首 <a class="header-anchor" href="#第2首" aria-label="Permalink to &quot;第2首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">皎洁得敢欺美玉的小人</p><p class="poem-stanza">也听人说秋天来了</p><p class="poem-stanza">便若有所思</p></div><h3 id="第3首" tabindex="-1">第3首 <a class="header-anchor" href="#第3首" aria-label="Permalink to &quot;第3首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">可哀的是秋风啊</p><p class="poem-stanza">从前难得涌出的泪</p><p class="poem-stanza">如今常常流下</p></div><h3 id="第4首" tabindex="-1">第4首 <a class="header-anchor" href="#第4首" aria-label="Permalink to &quot;第4首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">青色透明的悲珠</p><p class="poem-stanza">我枕着它睡</p><p class="poem-stanza">松涛听了一整夜</p></div><h3 id="第5首" tabindex="-1">第5首 <a class="header-anchor" href="#第5首" aria-label="Permalink to &quot;第5首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">神明都寂然的七山杉林</p><p class="poem-stanza">被染得如火，太阳落了</p><p class="poem-stanza">好静啊</p></div><h3 id="第6首" tabindex="-1">第6首 <a class="header-anchor" href="#第6首" aria-label="Permalink to &quot;第6首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">一读便懂得愁的那些书</p><p class="poem-stanza">古人竟拿去烧了</p><p class="poem-stanza">那份心性多好</p></div><h3 id="第7首" tabindex="-1">第7首 <a class="header-anchor" href="#第7首" aria-label="Permalink to &quot;第7首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">一切都显得虚而不实</p><p class="poem-stanza">就这样暗了下去</p><p class="poem-stanza">我收着这些悲日</p></div><h3 id="第8首" tabindex="-1">第8首 <a class="header-anchor" href="#第8首" aria-label="Permalink to &quot;第8首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">秋雨过后</p><p class="poem-stanza">积水里浮起一条红带</p><p class="poem-stanza">映着将暗的天空</p></div><h3 id="第9首" tabindex="-1">第9首 <a class="header-anchor" href="#第9首" aria-label="Permalink to &quot;第9首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">秋天起时，大约像水吧</p><p class="poem-stanza">一洗</p><p class="poem-stanza">什么念头都新了</p></div><h3 id="第10首" tabindex="-1">第10首 <a class="header-anchor" href="#第10首" aria-label="Permalink to &quot;第10首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">忧愁来了</p><p class="poem-stanza">我便登上小丘</p><p class="poem-stanza">不知名的鸟正啄着红棘果</p></div><h3 id="第11首" tabindex="-1">第11首 <a class="header-anchor" href="#第11首" aria-label="Permalink to &quot;第11首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">秋日的十字路口</p><p class="poem-stanza">风吹向四条路里的三条</p><p class="poem-stanza">寻不见风的去向</p></div><h3 id="第12首" tabindex="-1">第12首 <a class="header-anchor" href="#第12首" aria-label="Permalink to &quot;第12首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">秋声总比什么都先入耳</p><p class="poem-stanza">长着这样一副性子</p><p class="poem-stanza">命该是悲伤的</p></div><h3 id="第13首" tabindex="-1">第13首 <a class="header-anchor" href="#第13首" aria-label="Permalink to &quot;第13首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">山是看熟了的山</p><p class="poem-stanza">秋天一来</p><p class="poem-stanza">我肃然而望，只怕有神住</p></div><h3 id="第14首" tabindex="-1">第14首 <a class="header-anchor" href="#第14首" aria-label="Permalink to &quot;第14首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">我要做的，在人间已做完</p><p class="poem-stanza">长长的白日</p><p class="poem-stanza">竟这样可怜地想起万物</p></div><h3 id="第15首" tabindex="-1">第15首 <a class="header-anchor" href="#第15首" aria-label="Permalink to &quot;第15首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">雨沙沙地落下来</p><p class="poem-stanza">看庭院一寸寸湿了</p><p class="poem-stanza">我便想起要流泪</p></div><h3 id="第16首" tabindex="-1">第16首 <a class="header-anchor" href="#第16首" aria-label="Permalink to &quot;第16首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">梦里又见了</p><p class="poem-stanza">故乡寺院长廊上</p><p class="poem-stanza">被我踩碎的栉纹小蝶</p></div><h3 id="第17首" tabindex="-1">第17首 <a class="header-anchor" href="#第17首" aria-label="Permalink to &quot;第17首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">我试着</p><p class="poem-stanza">做回垂髫时的自己</p><p class="poem-stanza">开口说句话给人听</p></div><h3 id="第18首" tabindex="-1">第18首 <a class="header-anchor" href="#第18首" aria-label="Permalink to &quot;第18首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">秋风吹起</p><p class="poem-stanza">黍叶哗啦啦地响</p><p class="poem-stanza">想故乡的屋檐</p></div><h3 id="第19首" tabindex="-1">第19首 <a class="header-anchor" href="#第19首" aria-label="Permalink to &quot;第19首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">从相摩的肩缝之间</p><p class="poem-stanza">哪怕只匆匆瞥见一眼</p><p class="poem-stanza">我也记进了日记</p></div><h3 id="第20首" tabindex="-1">第20首 <a class="header-anchor" href="#第20首" aria-label="Permalink to &quot;第20首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">风流的人今古一样</p><p class="poem-stanza">老就老在</p><p class="poem-stanza">那玉手轻挽飞雪的夜里</p></div><h3 id="第21首" tabindex="-1">第21首 <a class="header-anchor" href="#第21首" aria-label="Permalink to &quot;第21首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">就像石板路上</p><p class="poem-stanza">被春天新长的草埋住</p><p class="poem-stanza">我偶然也肯忘了你</p></div><h3 id="第22首" tabindex="-1">第22首 <a class="header-anchor" href="#第22首" aria-label="Permalink to &quot;第22首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">昔年躺在摇篮里</p><p class="poem-stanza">多少次进我梦的那个人啊</p><p class="poem-stanza">亲得人心痛</p></div><h3 id="第23首" tabindex="-1">第23首 <a class="header-anchor" href="#第23首" aria-label="Permalink to &quot;第23首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">神无月</p><p class="poem-stanza">我想起岩手山中</p><p class="poem-stanza">初雪挨上眉梢的那个早晨</p></div><h3 id="第24首" tabindex="-1">第24首 <a class="header-anchor" href="#第24首" aria-label="Permalink to &quot;第24首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">久旱的雨沙沙落下</p><p class="poem-stanza">花圃里的萩</p><p class="poem-stanza">已经微微地乱了</p></div><h3 id="第25首" tabindex="-1">第25首 <a class="header-anchor" href="#第25首" aria-label="Permalink to &quot;第25首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">秋天的天空空廓无影</p><p class="poem-stanza">实在太寂寞了</p><p class="poem-stanza">乌鸦，你飞一只吧</p></div><h3 id="第26首" tabindex="-1">第26首 <a class="header-anchor" href="#第26首" aria-label="Permalink to &quot;第26首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">雨后的月亮</p><p class="poem-stanza">屋瓦湿得刚刚好</p><p class="poem-stanza">一处一处亮得人心酸</p></div><h3 id="第27首" tabindex="-1">第27首 <a class="header-anchor" href="#第27首" aria-label="Permalink to &quot;第27首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">我饿着的那一天</p><p class="poem-stanza">它摇着细瘦的尾巴</p><p class="poem-stanza">也饿着看我，那脸真好</p></div><h3 id="第28首" tabindex="-1">第28首 <a class="header-anchor" href="#第28首" aria-label="Permalink to &quot;第28首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">不知不觉</p><p class="poem-stanza">我连哭都忘了</p><p class="poem-stanza">难道再没有教我哭的人</p></div><h3 id="第29首" tabindex="-1">第29首 <a class="header-anchor" href="#第29首" aria-label="Permalink to &quot;第29首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">泪水汪然</p><p class="poem-stanza">啊，是酒的悲伤来找了我</p><p class="poem-stanza">起来舞一场吧</p></div><h3 id="第30首" tabindex="-1">第30首 <a class="header-anchor" href="#第30首" aria-label="Permalink to &quot;第30首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">蟋蟀叫了</p><p class="poem-stanza">我蹲在它旁边那块石头上</p><p class="poem-stanza">又哭又笑地自言自语</p></div><h3 id="第31首" tabindex="-1">第31首 <a class="header-anchor" href="#第31首" aria-label="Permalink to &quot;第31首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">从那场无力的病以后</p><p class="poem-stanza">我睡着总微张着口</p><p class="poem-stanza">竟成了习惯</p></div><h3 id="第32首" tabindex="-1">第32首 <a class="header-anchor" href="#第32首" aria-label="Permalink to &quot;第32首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">不过是得到一个人心这样的事</p><p class="poem-stanza">竟当作最大的心愿</p><p class="poem-stanza">年少的错</p></div><h3 id="第33首" tabindex="-1">第33首 <a class="header-anchor" href="#第33首" aria-label="Permalink to &quot;第33首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">那双从不怨人的</p><p class="poem-stanza">柔软的上视的眼</p><p class="poem-stanza">因是我爱，就偏要冷落么</p></div><h3 id="第34首" tabindex="-1">第34首 <a class="header-anchor" href="#第34首" aria-label="Permalink to &quot;第34首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">这样滚烫的泪</p><p class="poem-stanza">说是初恋的日子也有过</p><p class="poem-stanza">我又另哭了一天</p></div><h3 id="第35首" tabindex="-1">第35首 <a class="header-anchor" href="#第35首" aria-label="Permalink to &quot;第35首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">像重逢了</p><p class="poem-stanza">遗忘了很久很久的朋友</p><p class="poem-stanza">我这样欢喜地听水声</p></div><h3 id="第36首" tabindex="-1">第36首 <a class="header-anchor" href="#第36首" aria-label="Permalink to &quot;第36首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">秋夜那钢铁色的大空</p><p class="poem-stanza">我竟想着</p><p class="poem-stanza">里头也该有一座喷火的山</p></div><h3 id="第37首" tabindex="-1">第37首 <a class="header-anchor" href="#第37首" aria-label="Permalink to &quot;第37首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">岩手山啊</p><p class="poem-stanza">山下三面的野都满了虫声</p><p class="poem-stanza">它都怎么听</p></div><h3 id="第38首" tabindex="-1">第38首 <a class="header-anchor" href="#第38首" aria-label="Permalink to &quot;第38首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">秋像父亲那样可畏</p><p class="poem-stanza">又像母亲那样可亲</p><p class="poem-stanza">对我这没有家的孩子</p></div><h3 id="第39首" tabindex="-1">第39首 <a class="header-anchor" href="#第39首" aria-label="Permalink to &quot;第39首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">秋天来了</p><p class="poem-stanza">想念的心一刻没有空闲</p><p class="poem-stanza">整夜听雁，睡不着</p></div><h3 id="第40首" tabindex="-1">第40首 <a class="header-anchor" href="#第40首" aria-label="Permalink to &quot;第40首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">九月也过半了</p><p class="poem-stanza">我还要这样幼稚</p><p class="poem-stanza">不成人到几时</p></div><h3 id="第41首" tabindex="-1">第41首 <a class="header-anchor" href="#第41首" aria-label="Permalink to &quot;第41首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">那不肯说想念的人寄来的</p><p class="poem-stanza">勿忘草</p><p class="poem-stanza">也白成了一片</p></div><h3 id="第42首" tabindex="-1">第42首 <a class="header-anchor" href="#第42首" aria-label="Permalink to &quot;第42首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">像秋雨里反翘的弓</p><p class="poem-stanza">近来</p><p class="poem-stanza">你再也不肯使唤我了</p></div><h3 id="第43首" tabindex="-1">第43首 <a class="header-anchor" href="#第43首" aria-label="Permalink to &quot;第43首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">松风日夜地响</p><p class="poem-stanza">在无人来访的山祠里</p><p class="poem-stanza">响给石马的耳朵听</p></div><h3 id="第44首" tabindex="-1">第44首 <a class="header-anchor" href="#第44首" aria-label="Permalink to &quot;第44首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">朽木淡淡地香</p><p class="poem-stanza">加上里头蘑菇的香</p><p class="poem-stanza">秋已稍稍深了</p></div><h3 id="第45首" tabindex="-1">第45首 <a class="header-anchor" href="#第45首" aria-label="Permalink to &quot;第45首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">像一阵时雨的声音</p><p class="poem-stanza">穿过树林传过去</p><p class="poem-stanza">那群猿多么像人</p></div><h3 id="第46首" tabindex="-1">第46首 <a class="header-anchor" href="#第46首" aria-label="Permalink to &quot;第46首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">林子深处</p><p class="poem-stanza">远远地响起舂声</p><p class="poem-stanza">我莫是到了树洞里捣米的矮人国</p></div><h3 id="第47首" tabindex="-1">第47首 <a class="header-anchor" href="#第47首" aria-label="Permalink to &quot;第47首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">世界初开的时候</p><p class="poem-stanza">先有了森林</p><p class="poem-stanza">半神的人在里面守着火吧</p></div><h3 id="第48首" tabindex="-1">第48首 <a class="header-anchor" href="#第48首" aria-label="Permalink to &quot;第48首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">沙无边地连下去</p><p class="poem-stanza">住在戈壁旷野里的神</p><p class="poem-stanza">你该是秋的神吧</p></div><h3 id="第49首" tabindex="-1">第49首 <a class="header-anchor" href="#第49首" aria-label="Permalink to &quot;第49首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">天地之间</p><p class="poem-stanza">我的悲伤和月光</p><p class="poem-stanza">一般铺成这普照的秋夜</p></div><h3 id="第50首" tabindex="-1">第50首 <a class="header-anchor" href="#第50首" aria-label="Permalink to &quot;第50首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">夜里漏出的物响，可怜</p><p class="poem-stanza">我像一路拾着它们</p><p class="poem-stanza">这样游荡了过去</p></div><h3 id="第51首" tabindex="-1">第51首 <a class="header-anchor" href="#第51首" aria-label="Permalink to &quot;第51首&quot;">​</a></h3><div class="poem"><p class="poem-stanza">游子回到故乡睡下了</p><p class="poem-stanza">多么静</p><p class="poem-stanza">冬天真的来了</p></div></div>',4)])])}const z=s(l,[["render",t]]);export{h as __pageData,z as default};
